"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6475],{57565:e=>{e.exports=JSON.parse('{"functions":[{"name":"getFriendsInServer","desc":"Returns the players currently in the server who are friends with `player`.\\n`player` is never included in the result.\\n\\nUses `Player:IsFriendsWith()` per player, which may yield on a cache miss, so\\ntreat this as a yielding call rather than something to run every frame. Each\\npair\'s answer is memoized for the session after the first ask.\\n\\n```lua\\nfor _, friend in getFriendsInServer(player) do\\n\\thighlightPlayer(friend)\\nend\\n```","params":[{"name":"player","desc":"Player whose friends are being looked up","lua_type":"Player"}],"returns":[{"desc":"Friends present in this server","lua_type":"{ Player }"}],"function_type":"static","source":{"line":58,"path":"src/Shared/Modules/getFriendsInServer.luau"}}],"properties":[],"types":[],"name":"getFriendsInServer","desc":"Fetches the friends of a player that are also in this server.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":9,"path":"src/Shared/Modules/getFriendsInServer.luau"}}')}}]);